import { readFile } from "fs/promises";
import path from "path";
import type { HeroManifest } from "./types";

/**
 * Loads the frame manifest generated by `npm run frames`.
 *
 * Server-side only, and deliberately tolerant: if the extraction step has not
 * been run yet we return null so the hero can render a static fallback instead
 * of throwing during build.
 */
export async function loadHeroManifest(): Promise<HeroManifest | null> {
  const file = path.join(process.cwd(), "public", "hero-frames", "manifest.json");
  try {
    const raw = await readFile(file, "utf8");
    const json = JSON.parse(raw) as HeroManifest;
    if (!json?.output?.files?.length) return null;
    return json;
  } catch {
    return null;
  }
}
